import * as React from "react"
import { cn } from "cn"
import {
  Label as LabelPrimitive,
  Meter as MeterPrimitive,
  type LabelProps,
  type MeterProps as MeterPrimitiveProps,
} from "react-aria-components"

type MeterContextValue = {
  percentage?: number
  valueText?: string
}

const MeterContext = React.createContext<MeterContextValue | null>(null)

function useMeter() {
  const context = React.useContext(MeterContext)
  if (!context) {
    throw new Error("useMeter must be used within a Meter.")
  }

  return context
}

function MeterContent({
  children,
  percentage,
  valueText,
}: MeterContextValue & {
  children?: React.ReactNode
}) {
  const context = React.useMemo(
    () => ({ percentage, valueText }),
    [percentage, valueText]
  )

  return (
    <MeterContext value={context}>
      {children}
      <MeterTrack>
        <MeterIndicator />
      </MeterTrack>
    </MeterContext>
  )
}

function Meter({
  className,
  children,
  ...props
}: Omit<MeterPrimitiveProps, "children" | "className"> & {
  children?: React.ReactNode
  className?: string
}) {
  return (
    <MeterPrimitive
      data-slot="meter"
      className={cn("flex flex-wrap gap-3", className)}
      {...props}
    >
      {({ percentage, valueText }) => (
        <MeterContent percentage={percentage} valueText={valueText}>
          {children}
        </MeterContent>
      )}
    </MeterPrimitive>
  )
}

function MeterTrack({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      className={cn(
        "relative flex h-1 w-full items-center overflow-x-hidden rounded-full bg-muted",
        className
      )}
      data-slot="meter-track"
      {...props}
    />
  )
}

function MeterIndicator({
  className,
  style,
  ...props
}: React.ComponentProps<"span">) {
  const { percentage } = useMeter()

  return (
    <span
      data-slot="meter-indicator"
      className={cn("h-full bg-primary transition-all", className)}
      style={{
        ...style,
        width: `${percentage ?? 0}%`,
      }}
      {...props}
    />
  )
}

function MeterLabel({ className, ...props }: LabelProps) {
  return (
    <LabelPrimitive
      className={cn("text-sm font-medium", className)}
      data-slot="meter-label"
      {...props}
    />
  )
}

function MeterValue({
  className,
  children,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  children?: (value: string) => React.ReactNode
}) {
  const { valueText } = useMeter()
  return (
    <span
      className={cn(
        "ml-auto text-sm text-muted-foreground tabular-nums",
        className
      )}
      data-slot="meter-value"
      {...props}
    >
      {children && valueText != null ? children(valueText) : valueText}
    </span>
  )
}

export { Meter, MeterTrack, MeterIndicator, MeterLabel, MeterValue }
